{"cards": [{"node_code": "N_c0b9499ab3964a45", "definition": "研究管道运输系统中直管段的结构形式、几何尺寸、壁厚计算、材料选型及制造工艺的学科分支。", "boundary": "本节点聚焦于管道本体（直管）的设计与制造。边界在于区分“直管”与“管件”：本节点针对长距离输送的直线管段，关注其承压能力、抗疲劳性能及连接方式；而弯头、三通等异形部件归入“管件”。若涉及管道在特定地形下的敷设或线路走向，归入“管道线路工程”；若涉及管材的基础冶金性能，归入“管道材料”。", "includes": ["直管段的强度计算、壁厚确定与结构设计", "管道连接方式（焊接、法兰等）的结构设计", "直管段的制造工艺、质量控制与标准规范"], "excludes": ["弯头、三通、异径管等异形管件的设计（归入管件）", "管道线路的选线、路由规划及站场布置（归入管道线路工程）"], "sibling_distinctions": [{"other_code": "N_0f42233e69689bdb", "rule": "本节点针对直线管段；管件节点针对弯头、三通、异径管等改变流向或尺寸的异形部件。"}, {"other_code": "N_30f20a9b976f8029", "rule": "本节点关注通用直管的结构设计；各种管道节点可能涉及特定介质（如油、气、水）管道的综合设计或分类。"}], "cross_boundary_rule": "涉及管道壁厚计算时，若基于流体压力、温度及材料许用应力进行结构设计，归入本节点；若涉及材料在特定环境下的腐蚀减薄对寿命的影响，需结合管道腐蚀及防护节点，但主挂载仍为结构设计。"}, {"node_code": "N_0f42233e69689bdb", "definition": "研究管道运输系统中弯头、三通、异径管、管帽等异形管件的结构设计、制造工艺及性能要求的学科分支。", "boundary": "本节点专门针对管道系统中的非直管部件。边界在于区分“管件”与“直管”：本节点关注改变流向、分支或连接不同直径管道的部件，如弯头、三通、大小头；而长距离输送的直线管段归入“管”。若涉及管件在系统中的具体安装位置或布局，归入“管道线路工程”；若涉及管件材料的基础性能，归入“管道材料”。", "includes": ["弯头、三通、异径管、管帽等管件的结构设计与强度计算", "管件的制造工艺（如冲压、焊接、推制）及质量控制", "管件与直管连接的结构设计及标准规范"], "excludes": ["长距离输送的直线管段设计（归入管）", "管件在系统中的具体安装位置或布局（归入管道线路工程）"], "sibling_distinctions": [{"other_code": "N_c0b9499ab3964a45", "rule": "本节点针对弯头、三通等异形部件；管节点针对长距离输送的直线管段。"}, {"other_code": "N_30f20a9b976f8029", "rule": "本节点关注通用管件的结构设计；各种管道节点可能涉及特定介质管道的综合设计或分类。"}], "cross_boundary_rule": "涉及管件壁厚计算时，若基于流体压力、温度及材料许用应力进行结构设计，归入本节点；若涉及材料在特定环境下的腐蚀减薄对寿命的影响，需结合管道腐蚀及防护节点，但主挂载仍为结构设计。"}, {"node_code": "N_f2b88ace54f5fdc0", "definition": "研究管道运输系统中输油泵、压缩机等动力设备的结构形式、工作原理、选型计算及制造工艺的学科分支。", "boundary": "本节点聚焦于管道运输系统中的动力设备。边界在于区分“泵/压缩机”与“阀门/仪表”：本节点关注提供流体输送动力的设备，如离心泵、螺杆泵、压缩机；而控制流体通断或调节流量的设备归入“阀”，测量与监控设备归入“仪表”。若涉及泵/压缩机在站场中的具体布置或安装工艺，归入“管道线路工程”或“管道施工与机械”。", "includes": ["输油泵、压缩机等动力设备的结构设计与强度计算", "动力设备的工作原理、性能曲线及选型计算", "动力设备的制造工艺、质量控制及标准规范"], "excludes": ["阀门、仪表等控制与测量设备的设计（归入阀或仪表）", "动力设备在站场中的具体布置或安装工艺（归入管道线路工程或管道施工与机械）"], "sibling_distinctions": [{"other_code": "N_865cc0d0157580db", "rule": "本节点针对提供输送动力的泵/压缩机；阀节点针对控制流体通断或调节流量的阀门。"}, {"other_code": "N_d92f8b32ee534222", "rule": "本节点针对动力设备；仪表节点针对测量与监控流体参数（如压力、流量、温度）的仪表。"}], "cross_boundary_rule": "涉及泵/压缩机选型时，若基于输送流量、压力及介质特性进行结构设计，归入本节点；若涉及设备在特定环境下的腐蚀防护，需结合管道腐蚀及防护节点，但主挂载仍为设备设计。"}]}
